package org.sleepwell.app;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.os.*;import android.view.*;import android.view.inspector.WindowInspector;import android.widget.*;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.junit.Test;import java.io.*;import java.util.*;import java.util.concurrent.*;import static org.junit.Assert.*;
/** Config and explicit silent previews only. Never launches AlarmActivity or any service. */
public final class TypedWakeFlowTest {
 final Instrumentation i=InstrumentationRegistry.getInstrumentation();final Context c=i.getTargetContext();final UiDevice d=UiDevice.getInstance(i);final List<Activity> owned=new CopyOnWriteArrayList<>();Activity activity;String diary,database;DiaryStore.Factory diaryFactory;Records.Factory records;int schedules;
 interface Task{void run()throws Exception;}interface Check{boolean ready()throws Exception;}void waitFor(Check check)throws Exception{long limit=SystemClock.elapsedRealtime()+12000;while(!check.ready()){if(SystemClock.elapsedRealtime()>limit)throw new AssertionError("Typed wake fixture did not reach the expected state");Thread.sleep(30);}}
 void fixture(Task task)throws Exception{assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertEquals("1",d.executeShellCommand("getprop ro.kernel.qemu").trim());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));String original;try(Store store=new Store(c)){original=BackupFingerprint.read(store);}Map<String,?> preferences=new HashMap<>(Prefs.of(c).getAll());DiaryStore.Factory previousDiary=DiaryStore.factory;Records.Factory previousRecords=Records.factory;AlarmScheduling.Port previousSchedule=AlarmScheduling.port;diary="typed-diary-"+UUID.randomUUID()+".db";database="typed-alarm-"+UUID.randomUUID()+".db";diaryFactory=context->new DiaryStore(context,diary);records=context->new Store(context,database);DiaryStore.factory=diaryFactory;Records.factory=records;AlarmScheduling.port=new AlarmScheduling.Port(){public boolean allowed(Context context){return true;}public void schedule(Context context,Alarm alarm){assertFalse(alarm.enabled);schedules++;}};Application app=(Application)c.getApplicationContext();Application.ActivityLifecycleCallbacks callback=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){assertFalse("Actual alarm runtime forbidden",a instanceof AlarmActivity);owned.add(a);}public void onActivityResumed(Activity a){activity=a;}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callback);boolean quiet=false;
 try{task.run();}catch(Exception|AssertionError failure){try{d.takeScreenshot(new File(folder(),"typed-wake-failure.png"));d.dumpWindowHierarchy(new File(folder(),"typed-wake-failure.xml"));}catch(Exception diagnostic){failure.addSuppressed(diagnostic);}throw failure;}finally{try{JournalWrites.drain();DiaryJobs.drain(diaryFactory);waitFor(()->{i.runOnMainSync(()->{for(Activity a:owned)if(!a.isDestroyed()&&!a.isFinishing())a.finish();});return owned.stream().allMatch(Activity::isDestroyed);});JournalWrites.drain();DiaryJobs.drain(diaryFactory);DiaryJobs.forget(diaryFactory);quiet=true;}finally{app.unregisterActivityLifecycleCallbacks(callback);DiaryStore.factory=previousDiary;Records.factory=previousRecords;AlarmScheduling.port=previousSchedule;try(Store store=new Store(c)){assertEquals(original,BackupFingerprint.read(store));}assertEquals(preferences,Prefs.of(c).getAll());assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(c,"ringing"));if(quiet){c.deleteDatabase(diary);c.deleteDatabase(database);}}}}
 View root(){for(View root:WindowInspector.getGlobalWindowViews())if(root.hasWindowFocus()&&root.isAttachedToWindow()&&root.getContext().getPackageName().equals(c.getPackageName()))return root;return null;}
 View find(View view,String label){if(view==null)return null;if(label.contentEquals(view.getContentDescription()==null?"":view.getContentDescription())||view instanceof TextView&&label.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++){View found=find(group.getChildAt(n),label);if(found!=null)return found;}}return null;}
 Rect target(String label){Rect[] result={null};i.runOnMainSync(()->{View view=find(root(),label);while(view!=null&&!view.isClickable())view=view.getParent() instanceof View?(View)view.getParent():null;if(view==null||!view.isEnabled())return;Rect rect=new Rect();if(!view.getGlobalVisibleRect(rect)||rect.height()!=view.getHeight()||rect.width()!=view.getWidth()){view.requestRectangleOnScreen(new Rect(0,0,view.getWidth(),view.getHeight()),false);return;}if(rect.height()<Design.dp(c,48)||rect.width()<Design.dp(c,48))return;int[] screen=new int[2];view.getLocationOnScreen(screen);result[0]=new Rect(screen[0],screen[1],screen[0]+view.getWidth(),screen[1]+view.getHeight());});return result[0];}
 void frame()throws Exception{CountDownLatch commit=new CountDownLatch(1);i.runOnMainSync(()->{View root=root();assertNotNull(root);root.getViewTreeObserver().registerFrameCommitCallback(commit::countDown);root.invalidate();});assertTrue(commit.await(5,TimeUnit.SECONDS));}
 void click(String label)throws Exception{waitFor(()->target(label)!=null);frame();Rect rect=target(label);assertNotNull(label,rect);assertTrue(d.click(rect.centerX(),rect.centerY()));}
 void text(String label)throws Exception{waitFor(()->{boolean[] exists={false};i.runOnMainSync(()->exists[0]=find(root(),label)!=null);return exists[0];});}
 void input(String label,String value)throws Exception{UiObject2 field=d.wait(Until.findObject(By.desc(label)),4000);assertNotNull(label,field);field.setText(value);}
 boolean ime(){boolean[] visible={false};i.runOnMainSync(()->{View root=root();WindowInsets insets=root==null?null:root.getRootWindowInsets();visible[0]=insets!=null&&insets.isVisible(WindowInsets.Type.ime());});return visible[0];}void finishInput()throws Exception{if(ime()){assertTrue(d.pressBack());waitFor(()->!ime());}}
 File folder(){File f=new File(c.getExternalFilesDir(null),"verification");assertTrue(f.isDirectory()||f.mkdirs());return f;}void capture(String name,String label)throws Exception{text(label);frame();assertTrue(d.takeScreenshot(new File(folder(),"typed-wake-"+name+".png")));}
 void launch(Intent intent)throws Exception{Activity owner=i.startActivitySync(intent.putExtra("visualReview",true).putExtra("verificationLabel","TEST FIXTURE · silent preview / private diary").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));activity=owner;waitFor(owner::hasWindowFocus);}void recreate()throws Exception{Activity previous=activity;i.runOnMainSync(previous::recreate);waitFor(()->activity!=previous&&activity.hasWindowFocus());}
 @Test public void orderedMirrorAndJournalSettingsSaveRecreateAndReopen()throws Exception{fixture(()->{Alarm fixture=new Alarm(838383);fixture.enabled=false;fixture.label="Silent typed fixture";try(Store store=records.open(c)){store.save(fixture);}launch(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",fixture.json().toString()));click("Challenges");click("Configure Mirror text");capture("config-mirror","Use Mirror text");click("Rounds");click("2 rounds");click("Use Mirror text");click("Configure Dream journal");click("Entry minimum");click("80 letters / digits");recreate();capture("config-journal","Use Dream journal");click("Use Dream journal");click("Save routine");click("Save alarm");waitFor(()->activity.isDestroyed());Alarm saved;try(Store store=records.open(c)){saved=store.alarm(fixture.id);assertEquals(3,saved.challenges().tasks.size());assertEquals("Mirror text",saved.challenges().tasks.get(1).type);assertEquals(2,saved.challenges().tasks.get(1).rounds);assertEquals(80,saved.challenges().tasks.get(2).journalMinimum);Backup.validate(store.backup());}assertEquals(1,schedules);launch(new Intent(c,AlarmEditorActivity.class).putExtra("alarm",saved.json().toString()));click("Challenges");capture("config-reopened","Edit task 3 Dream journal");});}
 @Test public void silentMirrorJournalAndDiaryActionsRequireRealInputAndPersistence()throws Exception{fixture(()->{launch(new Intent(c,TypedWakePreviewActivity.class).putExtra("type","Mirror text"));capture("mirror","Check mirrored phrase");input("Mirror phrase answer","WRONG");finishInput();click("Check mirrored phrase");capture("mirror-error","Type the entire phrase normally, including its digits.");String run=((TypedWakePreviewActivity)activity).run;String phrase=MirrorText.phrase(run,0);input("Mirror phrase answer",phrase);finishInput();recreate();assertEquals(phrase,d.findObject(By.desc("Mirror phrase answer")).getText());click("Check mirrored phrase");text("Challenge completed");launch(new Intent(c,TypedWakePreviewActivity.class).putExtra("type","Dream journal").putExtra("minimum",40));input("Journal challenge entry","Too short");finishInput();click("Save entry & continue");capture("journal-short","Write at least 40 letters or digits.");input("Journal challenge entry",DiaryStorageTest.TEXT);finishInput();click("Save entry & continue");text("Challenge completed");try(DiaryStore store=diaryFactory.open(c)){assertEquals(1,store.count());assertEquals(DiaryStorageTest.TEXT,store.entries().get(0).text);}capture("journal-saved","Open private diary");click("Open private diary");text("Morning journal");capture("diary-list","Write diary entry");click("Morning journal");text("Diary entry");input("Diary title","Edited dream");input("Diary entry text",DiaryStorageTest.TEXT+" I also remembered the warm sunlight.");finishInput();click("Save diary entry");text("Edited dream");click("Edited dream");assertTrue(d.findObject(By.desc("Diary entry text")).getText().contains("warm sunlight"));capture("diary-edited","Save diary entry");click("Delete diary entry");capture("diary-delete","Delete entry");click("Cancel");try(DiaryStore store=diaryFactory.open(c)){assertEquals(1,store.count());assertEquals(1,new org.json.JSONObject(new String(store.export(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("entries").length());}click("Delete diary entry");click("Delete entry");text("No diary entries yet");capture("diary-empty","Write diary entry");try(DiaryStore store=diaryFactory.open(c)){assertEquals(0,store.count());}assertEquals(0,schedules);});}
}
